// ==============================================================================
// IVA NAIL ART NY — BOUTIQUE WHATSAPP CONCIERGE & AUTO-RESPONDER PARSER
// Atelier Privado en Bay Ridge, Brooklyn (11209) — Master Artist Ivannía Rodríguez
// ==============================================================================

const body = $input.item.json.body || $input.item.json;

// WhatsApp Cloud API / Twilio payload extraction
let fromPhone = '';
let incomingText = '';
let senderName = 'Hermosa';

if (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]) {
  const value = body.entry[0].changes[0].value || {};
  const contact = (value.contacts && value.contacts[0]) || {};
  const message = (value.messages && value.messages[0]) || {};
  fromPhone = message.from || contact.wa_id || '';
  senderName = (contact.profile && contact.profile.name) ? contact.profile.name.trim() : 'Hermosa';
  if (message.text && message.text.body) {
    incomingText = message.text.body;
  } else if (message.type === 'interactive') {
    incomingText = (message.interactive && message.interactive.button_reply && message.interactive.button_reply.title) || '';
  }
} else {
  fromPhone = body.from || body.phone || body.sender || '';
  incomingText = body.text || body.message || body.body || '';
  senderName = body.name || body.clientName || 'Hermosa';
}

// Normalize phone (E.164 digits)
let cleanPhone = (fromPhone || '').replace(/\D/g, '');
if (cleanPhone.length === 10) cleanPhone = `1${cleanPhone}`;

const rawQuery = (incomingText || '').trim();
const query = rawQuery.toLowerCase();

// Studio Constants
const STUDIO_LOCATION = 'Bay Ridge, Brooklyn, NY 11209';
const STUDIO_DEPOSIT = 35;
const STUDIO_PHONE = '+1 (929) 625-7273';
const STUDIO_WHATSAPP_NUMBER = '19296257273';
const STUDIO_PAYMENTS = 'Zelle / Apple Pay: 929-625-7273 (Ivannia Rodriguez) | Venmo: @iva_nailart_nyc';

// Intent Classification
let intent = 'general_inquiry';
let autoReply = '';
let notifyOwner = false;

if (!rawQuery) {
  intent = 'empty_message';
  autoReply = `¡Hola ${senderName}! 🤍 Gracias por escribir al santuario privado de IVA Nail Art NY en Bay Ridge. ¿Cómo podemos consentirte hoy? (Pregúntanos por cotizaciones, disponibilidad semanal, depósito o ubicación). ✨`;
} else if (
  query.includes('pedicur') ||
  query.includes('pie') ||
  query.includes('cabello') ||
  query.includes('hair') ||
  query.includes('corte') ||
  query.includes('masaje') ||
  query.includes('tinte')
) {
  intent = 'out_of_scope';
  autoReply = `¡Hola ${senderName}! 🤍 En IVA Nail Art NY nos especializamos exclusivamente en acrílico esculpido de alta gama, manicura rusa y nail art artesanal en nuestro santuario privado de Bay Ridge. No realizamos pedicuras ni otros servicios generales.\n\nSi deseas un servicio exclusivo de uñas de manos o restaurar tu set, ¡estaremos encantadas de atenderte! 💅`;
} else if (
  query.includes('deposito') ||
  query.includes('depósito') ||
  query.includes('deposit') ||
  query.includes('zelle') ||
  query.includes('venmo') ||
  query.includes('apple pay') ||
  query.includes('apartar') ||
  query.includes('reserva')
) {
  intent = 'deposit_faq';
  autoReply = `✨ *IVA NAIL ART NY — Política de Depósito* ✨\nAtelier Privado en Bay Ridge, Brooklyn\n\n¡Hola ${senderName}! 🤍 Para asegurar tu fecha y horario exclusivo en nuestro atelier, requerimos un depósito no reembolsable de $${STUDIO_DEPOSIT} USD (este monto se deduce de tu total el día de tu cita).\n\n💳 *Métodos de Pago:*\n• Zelle / Apple Pay: 929-625-7273 (Ivannia Rodriguez)\n• Venmo: @iva_nailart_nyc\n\n🔒 Cuidamos tu tiempo y el nuestro: atendemos solo 2 a 3 clientas por día para garantizar máxima dedicación y esterilización de grado hospitalario.\n\nEnvíanos tu comprobante aquí para confirmar tu espacio. ✨`;
} else if (
  query.includes('donde') ||
  query.includes('dónde') ||
  query.includes('ubicacion') ||
  query.includes('ubicación') ||
  query.includes('direccion') ||
  query.includes('dirección') ||
  query.includes('location') ||
  query.includes('address') ||
  query.includes('metro') ||
  query.includes('subway') ||
  query.includes('bay ridge')
) {
  intent = 'location_faq';
  autoReply = `📍 *IVA NAIL ART NY — Ubicación del Santuario*\n\n¡Hola ${senderName}! 🤍 Estamos ubicadas en el corazón de Bay Ridge, Brooklyn, NY 11209, a pasos de la estación 86th St del tren R. Hay estacionamiento cómodo y gratuito en la calle.\n\nAl ser un atelier residencial privado 1 a 1, te enviaremos el número exacto y código de acceso 15 minutos antes de tu cita para tu total privacidad y seguridad. 💅\n\n¿Deseas consultar disponibilidad para esta semana? ✨`;
} else if (
  query.includes('cotiz') ||
  query.includes('precio') ||
  query.includes('cuanto') ||
  query.includes('cuánto') ||
  query.includes('costo') ||
  query.includes('quote') ||
  query.includes('price') ||
  query.includes('set') ||
  query.includes('diseño') ||
  query.includes('acrilic') ||
  query.includes('acrílic') ||
  query.includes('rusa') ||
  query.includes('biab') ||
  query.includes('relleno')
) {
  intent = 'quote_inquiry';
  notifyOwner = true;
  autoReply = `✨ *IVA NAIL ART NY — Cotización de Autor* ✨\nAtelier Privado en Bay Ridge, Brooklyn\n\n¡Hola ${senderName}! 🤍 Con gusto preparamos tu cotización personalizada. En nuestro estudio cada set es una pieza única realizada por Ivannía Rodríguez.\n\nPara darte el valor exacto, compártenos:\n1. 💅 *Servicio Base:* Acrílico esculpido, Relleno, Manicura rusa o Gel estructurado (BIAB).\n2. 📏 *Largo deseado:* Corto, Medio, Largo o XL.\n3. 🎨 *Nivel de Arte:* Minimalista, Mano alzada o 3D/Cristales.\n4. 🔄 *Retiro:* ¿Traes producto anterior de otro lugar? (Sí / No).\n5. 📸 *Foto de referencia:* ¡Adjúntanos tu diseño soñado!\n\nIvannía revisará tu diseño y te enviará la cotización personalizada enseguida. 💖`;
} else {
  intent = 'general_concierge';
  autoReply = `✨ *IVA NAIL ART NY — Santuario Privado* ✨\nBay Ridge, Brooklyn\n\n¡Hola ${senderName}! 🤍 Gracias por comunicarte con nosotras. Ivannía está atendiendo a una clienta en este momento en el santuario 💅.\n\nRevisaremos tu mensaje con mucho amor y te responderemos en un lapso de 1 a 2 horas.\n\nPara agendar tu cita directa en línea o ver nuestro lookbook:\n🌐 https://ivanailartny.com\n📸 Instagram: @iva_nailart_nyc\n\n¡Que tengas un día radiante! ✨`;
}

return {
  json: {
    senderName,
    fromPhone,
    cleanPhone,
    incomingText: rawQuery,
    intent,
    autoReply,
    notifyOwner,
    studioLocation: STUDIO_LOCATION,
    studioDeposit: STUDIO_DEPOSIT,
    studioPhone: STUDIO_PHONE,
    studioWhatsappNumber: STUDIO_WHATSAPP_NUMBER,
    timestamp: new Date().toISOString()
  }
};

